def L(sid, items, qs): return listen_set(sid, '听力 ' + sid[-1].upper(), IL, 'zh', items, qs, 'hsk')
def O(items, ans_sentence, alt=None):
    q = {'type': 'order', 'prompt': '完成句子：把词语排成正确的句子。', 'items': items, 'explain': ans_sentence}
    if alt: q['alt'] = alt
    return q
def GP(prompt, ans, exp_id, exp_en):
    return {'type': 'gap', 'prompt': prompt, 'answer': [ans], 'explain': E(exp_id, exp_en), 'group': '看拼音写汉字'}
