  M('外面下雨了，你（　）带伞吧。', ['最好', '因为', '虽然', '就是'], S2, E('最好 = sebaiknya.', '最好 = had better.')),
  M('(短文) 马丁来中国多长时间了？', ['两年', '一年', '三年', '两个月'], S3, E('已经两年了。', 'Two years.')),
